#include <iostream>
#include <string>
using namespace std;
int main() {
    string s;
    cin >> s;
    string t;
    for (char c : s) {
        if (c != '.') {
            t += c;
        }
    }
    cout << t << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
int main() {
    string s;
    cin >> s;
    s.erase(remove(s.begin(), s.end(), '.'), s.end());
    cout << s << endl;
    return 0;
}
